from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one match, got {count}: {old!r}")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")


cpp = "apps/ied_simulator/src/IedSimulatorController.cpp"

# Python re.sub treats backslash escapes in replacement templates. Repair the
# two C++ character literals generated by the large structural replacement.
replace_once(cpp, "    command += '\n';\n", "    command += '\\n';\n")
replace_once(
    cpp,
    "    const auto key = domain + QLatin1Char('\n') + itemName;\n",
    "    const auto key = domain + QLatin1Char('\\n') + itemName;\n",
)

# materializedValueMap appears before the helper body. A forward declaration
# keeps the helper close to the manifest/event encoding helpers while making
# the initial state metadata available during materialization.
replace_once(
    cpp,
    "QVariantMap materializedValueMap(const arstack::iedsim::MaterializedSclValue& value) {\n",
    "QString deterministicTimestamp(quint64 milliseconds);\n\n"
    "QVariantMap materializedValueMap(const arstack::iedsim::MaterializedSclValue& value) {\n",
)

print("P1 generated-source repair applied")
